#!/usr/bin/env python3
"""Load each historical RDB snapshot under Redis 7.2 and record encodings.

Each (file, mode) pair gets a private working directory containing only a copy
of that one RDB file, loaded via dir + dbfilename. Logs/pidfiles live outside
the data dir so it stays clean; snapshotting is disabled and shutdown is
NOSAVE so the copies are never rewritten.
"""
import json, os, shutil, socket, subprocess, sys, time

WORK = "/var/tmp/redis-rdb-work"
SERVER = "/app/src/redis-server"
SRC = "/data/rdb"
HOST = "127.0.0.1"


class Client:
    """Minimal RESP client."""

    def __init__(self, host, port, timeout=10):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.buf = b""

    def cmd(self, *args):
        out = b"*%d\r\n" % len(args)
        for a in args:
            if not isinstance(a, bytes):
                a = str(a).encode()
            out += b"$%d\r\n%s\r\n" % (len(a), a)
        self.sock.sendall(out)
        return self._reply()

    def _line(self):
        while b"\r\n" not in self.buf:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise EOFError("connection closed")
            self.buf += chunk
        line, self.buf = self.buf.split(b"\r\n", 1)
        return line

    def _read(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise EOFError("connection closed")
            self.buf += chunk
        data, self.buf = self.buf[:n], self.buf[n:]
        return data

    def _reply(self):
        line = self._line()
        kind, rest = line[:1], line[1:]
        if kind == b"+":
            return rest.decode()
        if kind == b"-":
            raise RuntimeError(rest.decode())
        if kind == b":":
            return int(rest)
        if kind == b"$":
            n = int(rest)
            if n == -1:
                return None
            data = self._read(n + 2)[:-2]
            return data.decode()
        if kind == b"*":
            n = int(rest)
            if n == -1:
                return None
            return [self._reply() for _ in range(n)]
        raise RuntimeError("bad RESP: %r" % line)

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass


def start(tag, rdb, port, overrides, daemon=False):
    """Copy one rdb into a private dir and start redis-server on it."""
    datadir = os.path.join(WORK, "runs", tag)
    shutil.rmtree(datadir, ignore_errors=True)
    os.makedirs(datadir)
    shutil.copy2(os.path.join(SRC, rdb), os.path.join(datadir, rdb))

    conf = os.path.join(WORK, "conf", tag + ".conf")
    log = os.path.join(WORK, "logs", tag + ".log")
    lines = [
        "bind %s" % HOST,
        "port %d" % port,
        "dir %s" % datadir,
        "dbfilename %s" % rdb,
        'save ""',
        "appendonly no",
        "logfile %s" % log,
        "pidfile %s" % os.path.join(WORK, "logs", tag + ".pid"),
        "protected-mode no",
    ]
    if daemon:
        lines.append("daemonize yes")
    lines += overrides
    with open(conf, "w") as fh:
        fh.write("\n".join(lines) + "\n")

    proc = subprocess.Popen([SERVER, conf])
    deadline = time.time() + 30
    while time.time() < deadline:
        if not daemon and proc.poll() is not None:
            raise RuntimeError("%s: server exited rc=%s, see %s" % (tag, proc.returncode, log))
        try:
            c = Client(HOST, port)
            if c.cmd("PING") == "PONG":
                return proc, c, datadir
            c.close()
        except (OSError, EOFError, RuntimeError):
            time.sleep(0.1)
    raise RuntimeError("%s: server did not come up, see %s" % (tag, log))

